1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Set;
5	import java.util.regex.Pattern;
6	
7	/**
8	 * Email normalization shared by the owner pipelines: decides whether an address is
9	 * syntactically valid and produces its canonical (lower-cased) form, so an owner's
10	 * email is validated and stored in one consistent representation.
11	 */
12	public final class OwnerEmail {
13	
14	    /** A syntactically valid address: {@code local@domain.tld} with no whitespace. */
15	    private static final Pattern VALID = Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
16	
17	    /** Domains of throwaway/disposable mailboxes that owners may not register with. */
18	    private static final Set<String> DISPOSABLE_DOMAINS =
19	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
20	
21	    private OwnerEmail() {
22	    }
23	
24	    /** Whether {@code email} is a syntactically valid address. */
25	    public static boolean isValid(String email) {
26	        return email != null && VALID.matcher(email).matches();
27	    }
28	
29	    /** The canonical, lower-cased form of {@code email}. */
30	    public static String normalize(String email) {
31	        return email.toLowerCase(Locale.ROOT);
32	    }
33	
34	    /** Whether {@code email}'s domain is on the disposable-domain blocklist. */
35	    public static boolean isDisposable(String email) {
36	        int at = email.lastIndexOf('@');
37	        if (at < 0) {
38	            return false;
39	        }
40	        return DISPOSABLE_DOMAINS.contains(email.substring(at + 1).toLowerCase(Locale.ROOT));
41	    }
42	}
